package com.opspilot.document; import java.util.*; import com.opspilot.document.dto.*; import com.opspilot.user.*; import com.opspilot.workspace.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DocumentService {private final DocumentRepository docs;private final UserRepository users;private final WorkspaceAccessService access;public DocumentService(DocumentRepository d,UserRepository u,WorkspaceAccessService a){docs=d;users=u;access=a;}
@Transactional public DocumentResponse create(Long wid,Long uid,CreateDocumentRequest r){WorkspaceMember m=access.requireMembership(wid,uid);User u=users.findById(uid).orElseThrow(DocumentNotFoundException::new);return DocumentResponse.from(docs.saveAndFlush(new Document(m.getWorkspace(),r.title().trim(),r.content(),u)));}
@Transactional(readOnly=true) public List<DocumentSummaryResponse> list(Long wid,Long uid,DocumentStatus s){access.requireMembership(wid,uid);return docs.findByWorkspace_IdAndStatusOrderByCreatedAtDesc(wid,s).stream().map(DocumentSummaryResponse::from).toList();}
@Transactional(readOnly=true) public DocumentResponse get(Long id,Long uid){return DocumentResponse.from(doc(id,uid));}
@Transactional public DocumentResponse update(Long id,Long uid,UpdateDocumentRequest r){Document d=doc(id,uid);canModify(d,uid);if(d.getStatus()==DocumentStatus.ARCHIVED)throw new ArchivedDocumentException();if(r.title()!=null&&r.title().isBlank())throw new InvalidDocumentUpdateException("Document title must not be blank");d.update(r.title()==null?null:r.title().trim(),r.content());return DocumentResponse.from(docs.saveAndFlush(d));}
@Transactional public DocumentResponse archive(Long id,Long uid){Document d=doc(id,uid);canModify(d,uid);if(d.getStatus()==DocumentStatus.ARCHIVED)return DocumentResponse.from(d);d.archive();return DocumentResponse.from(docs.saveAndFlush(d));}
private Document doc(Long id,Long uid){Document d=docs.findById(id).orElseThrow(DocumentNotFoundException::new);access.requireMembership(d.getWorkspace().getId(),uid);return d;}private void canModify(Document d,Long uid){WorkspaceMember m=access.requireMembership(d.getWorkspace().getId(),uid);if(m.getRole()==WorkspaceRole.OWNER||m.getRole()==WorkspaceRole.ADMIN||d.getCreatedBy().getId().equals(uid))return;throw new DocumentAccessDeniedException();}}
